1	// Package contractsentinel report: content-addressed, persistable audit reports.
2	package contractsentinel
3	
4	import (
5		"crypto/sha256"
6		"encoding/hex"
7		"encoding/json"
8		"fmt"
9		"os"
10		"path/filepath"
11		"sort"
12		"strings"
13		"unicode/utf8"
14	)
15	
16	// Check statuses recorded per rule in a report.
17	const (
18		StatusUnchecked   = "未检查"
19		StatusPass        = "通过"
20		StatusDefect      = "发现缺陷"
21		StatusToolMissing = "工具缺失"
22		StatusTimeout     = "超时"
23	)
24	
25	// ReportArtifact identifies the audited artifact by name and content hash.
26	type ReportArtifact struct {
27		Name string `json:"name"`
28		Hash string `json:"hash"`
29	}
30	
31	// ReportRule is one rule together with the invariant check result. The note
32	// carries the original checker description: counterexample evidence for a
33	// defect, a tool availability remark for 工具缺失, a deadline remark for 超时,
34	// or an optional remark for a passing check. It is empty for reports built
35	// only from invariant booleans.
36	type ReportRule struct {
37		ID          string `json:"id"`
38		Kind        string `json:"kind"`
39		Severity    string `json:"severity"`
40		Invariant   string `json:"invariant"`
41		RequiresABI bool   `json:"requiresABI"`
42		Version     string `json:"version"`
43		Status      string `json:"status"`
44		Note        string `json:"note,omitempty"`
45	}
46	
47	// ReportFinding binds a defect to its artifact, rule, version and evidence.
48	type ReportFinding struct {
49		ArtifactHash string `json:"artifactHash"`
50		RuleID       string `json:"ruleId"`
51		Version      string `json:"version"`
52		Severity     string `json:"severity"`
53		Invariant    string `json:"invariant"`
54		Evidence     string `json:"evidence"`
55	}
56	
57	// Report is the persisted audit result.
58	type Report struct {
59		ReportID string          `json:"reportId"`
60		Artifact ReportArtifact  `json:"artifact"`
61		Rules    []ReportRule    `json:"rules"`
62		Findings []ReportFinding `json:"findings"`
63	}
64	
65	// wireArtifact is the JSON shape of an artifact in an audit submission.
66	type wireArtifact struct {
67		Name     string `json:"name"`
68		ABI      string `json:"abi"`
69		Bytecode string `json:"bytecode"`
70		Source   string `json:"source"`
71	}
72	
73	// wireRule is the JSON shape of a rule in an audit submission.
74	type wireRule struct {
75		ID          string `json:"id"`
76		Kind        string `json:"kind"`
77		Severity    string `json:"severity"`
78		Invariant   string `json:"invariant"`
79		RequiresABI bool   `json:"requiresABI"`
80		Version     string `json:"version"`
81	}
82	
83	// CheckRecord is one imported per-rule check result: the artifact hash and
84	// rule version it was produced against, the conclusion status, and the
85	// original checker note (counterexample, tool or deadline remark).
86	type CheckRecord struct {
87		ArtifactHash string
88		RuleID       string
89		Version      string
90		Status       string
91		Note         string
92	}
93	
94	// wireCheck is the JSON shape of one entry in the checks array.
95	type wireCheck struct {
96		ArtifactHash string `json:"artifactHash"`
97		RuleID       string `json:"ruleId"`
98		Version      string `json:"version"`
99		Status       string `json:"status"`
100		Note         string `json:"note"`
101	}
102	
103	// wireInput is the JSON object accepted by the audit command.
104	type wireInput struct {
105		Artifact   wireArtifact               `json:"artifact"`
106		Rules      []wireRule                 `json:"rules"`
107		Invariants map[string]json.RawMessage `json:"invariants"`
108		Checks     []wireCheck                `json:"checks"`
109	}
110	
111	// submissionShape is the fixed-field shape of an audit submission: the agreed
112	// spellings at the top level and inside the artifact, every rule and every
113	// check record. The invariants object is a fixed top-level member but has no
114	// nested shape, so it passes through untouched: invariant names are
115	// user-defined rather than fixed fields, and "Inv" and "inv" stay two
116	// independent invariants and a padded name is not trimmed.
117	var submissionShape = fixedShape{
118		keys: []string{"artifact", "rules", "invariants", "checks"},
119		objects: map[string]fixedShape{
120			"artifact": {keys: []string{"name", "abi", "bytecode", "source"}},
121		},
122		arrays: map[string]fixedShape{
123			"rules":  {keys: []string{"id", "kind", "severity", "invariant", "requiresABI", "version"}},
124			"checks": {keys: []string{"artifactHash", "ruleId", "version", "status", "note"}},
125		},
126	}
127	
128	// strictSubmissionJSON rewrites submission bytes to the fixed submission
129	// fields under their agreed spelling; see fixedShape for the recognition
130	// convention shared with the archive read side.
131	func strictSubmissionJSON(data []byte) ([]byte, error) {
132		return strictFixedJSON(data, submissionShape)
133	}
134	
135	// validateFormalCheckStatuses checks the formal "status" member of every
136	// strict check record. The strict rewrite dropped extension members, so the
137	// status seen here is the agreed-spelling one alone: a missing formal status,
138	// a non-string one, or an unsupported value rejects the whole submission
139	// even when an adjacent "StAtus" extension member carried a legal-looking
140	// value. The error names the rule the record is for so the offending entry is
141	// identifiable.
142	func validateFormalCheckStatuses(strict []byte) error {
143		var top struct {
144			Checks []map[string]json.RawMessage `json:"checks"`
145		}
146		if err := json.Unmarshal(strict, &top); err != nil {
147			return errInvalid("invalid JSON: " + err.Error())
148		}
149		for _, rec := range top.Checks {
150			where := "check record"
151			if raw, ok := rec["ruleId"]; ok {
152				var ruleID string
153				if err := json.Unmarshal(raw, &ruleID); err == nil && ruleID != "" {
154					where = "check for rule " + ruleID
155				}
156			}
157			raw, ok := rec["status"]
158			if !ok {
159				return errInvalid(where + ": status is required")
160			}
161			var status string
162			if err := json.Unmarshal(raw, &status); err != nil {
163				return errInvalid(where + ": status must be a string")
164			}
165			if !validCheckStatus(status) {
166				return errInvalid(where + ": unknown status " + status)
167			}
168		}
169		return nil
170	}
171	
172	// validateFormalRequiresABI checks the formal "requiresABI" member of every
173	// strict rule definition. The strict rewrite dropped extension members, so the
174	// value seen here is the agreed-spelling one alone. Decoding the member
175	// straight into a Go bool would turn null into the zero value false: a rule
176	// whose requirement was never actually stated would be recorded as not
177	// needing an ABI, indistinguishable from an explicit false, and could even
178	// produce a defect finding from a false invariant. When the formal member is
179	// present its value must be the JSON boolean true or false — null, a string,
180	// a number, an object or an array rejects the whole submission, whether or
181	// not the artifact carries an ABI and whether or not the rule received any
182	// check conclusion. An omitted member still means false. A case-variant or
183	// whitespace-padded name is extension data and its value, null included,
184	// never reaches this check; it can neither trigger the error nor rescue an
185	// illegal formal value. The error names the rule so the offending entry is
186	// identifiable.
187	func validateFormalRequiresABI(strict []byte) error {
188		var top struct {
189			Rules []map[string]json.RawMessage `json:"rules"`
190		}
191		if err := json.Unmarshal(strict, &top); err != nil {
192			return errInvalid("invalid JSON: " + err.Error())
193		}
194		for _, rule := range top.Rules {
195			where := "rule"
196			if raw, ok := rule["id"]; ok {
197				var id string
198				if err := json.Unmarshal(raw, &id); err == nil && id != "" {
199					where = "rule " + id
200				}
201			}
202			raw, ok := rule["requiresABI"]
203			if !ok {
204				continue
205			}
206			var token any
207			if err := json.Unmarshal(raw, &token); err != nil {
208				return errInvalid(where + ": requiresABI must be a boolean")
209			}
210			if _, isBool := token.(bool); !isBool {
211				return errInvalid(where + ": requiresABI must be a boolean")
212			}
213		}
214		return nil
215	}
216	
217	// ParseAuditInput decodes an audit submission JSON object into domain values.
218	// Invariant values must be JSON booleans; any other type is an error. A formal
219	// requiresABI member on a rule must likewise be a JSON boolean: null or any
220	// non-boolean value rejects the whole submission instead of being read as the
221	// zero value false, while an omitted member still means false. Any JSON
222	// object in the submission that repeats a member name rejects the whole
223	// submission: the decoder keeps only the last value silently, so a repeated
224	// invariant key would choose a conclusion by member order instead of giving
225	// one trustworthy result. A character the decoder would silently rewrite — an
226	// invalid UTF-8 byte, or an unpaired or wrongly ordered surrogate escape in
227	// any member name or string value, including values nested under unknown
228	// extension members — rejects the whole submission as an input error before
229	// any content is hashed, so evidence and hashes always reflect the submitted
230	// bytes rather than a U+FFFD-rewritten copy. Only the fixed fields under their
231	// agreed spelling participate: case variants and whitespace-padded names are
232	// extension data and are ignored, so they can neither override a formal value
233	// nor supply one when the formal member is missing or unsupported. Invariant
234	// names are not fixed fields — they are user-defined, compared case
235	// sensitively and never trimmed.
236	func ParseAuditInput(data []byte) (Artifact, []Rule, map[string]bool, []CheckRecord, error) {
237		if charErr := validateJSONCharacters(data); charErr != nil {
238			return Artifact{}, nil, nil, nil, errInvalid(charErr.Error())
239		}
240		if dup := findDuplicateJSONMember(data); dup != nil {
241			return Artifact{}, nil, nil, nil, errInvalid(duplicateMemberMessage(data, dup))
242		}
243		strict, err := strictSubmissionJSON(data)
244		if err != nil {
245			return Artifact{}, nil, nil, nil, errInvalid("invalid JSON: " + err.Error())
246		}
247		if err := validateFormalCheckStatuses(strict); err != nil {
248			return Artifact{}, nil, nil, nil, err
249		}
250		if err := validateFormalRequiresABI(strict); err != nil {
251			return Artifact{}, nil, nil, nil, err
252		}
253		var in wireInput
254		if err := json.Unmarshal(strict, &in); err != nil {
255			return Artifact{}, nil, nil, nil, errInvalid("invalid JSON: " + err.Error())
256		}
257		invariants := make(map[string]bool, len(in.Invariants))
258		for key, raw := range in.Invariants {
259			// Only JSON true/false is a conclusion. Unmarshalling directly into a
260			// bool would turn null into the zero value false, which would falsely
261			// record a defect; require the token to be a boolean instead.
262			var token any
263			if err := json.Unmarshal(raw, &token); err != nil {
264				return Artifact{}, nil, nil, nil, errInvalid("invariant " + key + " must be a boolean")
265			}
266			holds, ok := token.(bool)
267			if !ok {
268				return Artifact{}, nil, nil, nil, errInvalid("invariant " + key + " must be a boolean")
269			}
270			invariants[key] = holds
271		}
272		artifact := Artifact{
273			Name:     in.Artifact.Name,
274			ABI:      in.Artifact.ABI,
275			Bytecode: in.Artifact.Bytecode,
276			Source:   in.Artifact.Source,
277		}
278		rules := make([]Rule, 0, len(in.Rules))
279		for _, wr := range in.Rules {
280			rules = append(rules, Rule{
281				ID:          wr.ID,
282				Kind:        wr.Kind,
283				Severity:    wr.Severity,
284				Invariant:   wr.Invariant,
285				RequiresABI: wr.RequiresABI,
286				Version:     wr.Version,
287			})
288		}
289		checks := make([]CheckRecord, 0, len(in.Checks))
290		for _, wc := range in.Checks {
291			checks = append(checks, CheckRecord{
292				ArtifactHash: wc.ArtifactHash,
293				RuleID:       wc.RuleID,
294				Version:      wc.Version,
295				Status:       wc.Status,
296				Note:         wc.Note,
297			})
298		}
299		return artifact, rules, invariants, checks, nil
300	}
301	
302	// ArtifactHash computes the content hash of an artifact. Only the raw ABI,
303	// bytecode and source strings contribute; field boundaries are explicit
304	// (length-prefixed) so that different splits never collide. The source is
305	// hashed as a field value, never read from disk, and the name does not
306	// participate.
307	func ArtifactHash(a Artifact) string {
308		h := sha256.New()
309		h.Write([]byte("contractsentinel-artifact-v1\n"))
310		for _, field := range []string{a.ABI, a.Bytecode, a.Source} {
311			fmt.Fprintf(h, "%d\n", len(field))
312			h.Write([]byte(field))
313		}
314		sum := h.Sum(nil)
315		return hex.EncodeToString(sum)
316	}
317	
318	// validCheckStatus reports whether status is one of the four recorded check
319	// conclusions.
320	func validCheckStatus(status string) bool {
321		switch status {
322		case StatusPass, StatusDefect, StatusToolMissing, StatusTimeout:
323			return true
324		}
325		return false
326	}
327	
328	// BuildReport evaluates rules against the artifact and invariant values and
329	// imported check records and produces the report to persist. Insufficient
330	// inputs (missing ABI for a rule that requires it, missing bytecode for a
331	// symbolic rule) fail the whole submission and are never recorded as defects.
332	// Imported checks are validated as a whole: unknown rules, duplicate records,
333	// unknown statuses, missing notes, hash or version mismatches, and a rule
334	// receiving both a check record and an invariant boolean all reject the
335	// submission without producing a report.
336	func BuildReport(artifact Artifact, rules []Rule, invariants map[string]bool, checks []CheckRecord) (Report, error) {
337		if artifact.Name == "" {
338			return Report{}, errInvalid("artifact name is required")
339		}
340		hash := ArtifactHash(artifact)
341		seen := make(map[string]bool, len(rules))
342		ruleByID := make(map[string]Rule, len(rules))
343		for _, rule := range rules {
344			if rule.ID == "" {
345				return Report{}, errInvalid("rule id is required")
346			}
347			if rule.Version == "" {
348				return Report{}, errInvalid("rule " + rule.ID + " version is required")
349			}
350			if seen[rule.ID] {
351				return Report{}, errInvalid("duplicate rule id " + rule.ID)
352			}
353			seen[rule.ID] = true
354			ruleByID[rule.ID] = rule
355			if rule.RequiresABI && artifact.ABI == "" {
356				return Report{}, errInvalid("rule " + rule.ID + " requires an ABI")
357			}
358			if rule.Kind == "symbolic" && artifact.Bytecode == "" {
359				return Report{}, errInvalid("symbolic rule " + rule.ID + " requires bytecode")
360			}
361		}
362		checkByRule := make(map[string]CheckRecord, len(checks))
363		for _, check := range checks {
364			if check.RuleID == "" {
365				return Report{}, errInvalid("check rule id is required")
366			}
367			rule, ok := ruleByID[check.RuleID]
368			if !ok {
369				return Report{}, errInvalid("check for rule " + check.RuleID + ": unknown rule")
370			}
371			if _, dup := checkByRule[check.RuleID]; dup {
372				return Report{}, errInvalid("duplicate check for rule " + check.RuleID)
373			}
374			if check.ArtifactHash != hash {
375				return Report{}, errInvalid("check for rule " + check.RuleID + ": artifact hash mismatch")
376			}
377			if check.Version != rule.Version {
378				return Report{}, errInvalid("check for rule " + check.RuleID + ": version mismatch")
379			}
380			if !validCheckStatus(check.Status) {
381				return Report{}, errInvalid("check for rule " + check.RuleID + ": unknown status " + check.Status)
382			}
383			if check.Status != StatusPass && strings.TrimSpace(check.Note) == "" {
384				return Report{}, errInvalid("check for rule " + check.RuleID + ": note is required for status " + check.Status)
385			}
386			if _, hasInvariant := invariants[rule.Invariant]; hasInvariant {
387				return Report{}, errInvalid("rule " + check.RuleID + ": both a check record and an invariant value are provided")
388			}
389			checkByRule[check.RuleID] = check
390		}
391		report := Report{
392			Artifact: ReportArtifact{Name: artifact.Name, Hash: hash},
393			Rules:    []ReportRule{},
394			Findings: []ReportFinding{},
395		}
396		for _, rule := range rules {
397			status := StatusUnchecked
398			note := ""
399			if check, ok := checkByRule[rule.ID]; ok {
400				status = check.Status
401				note = check.Note
402			} else if holds, checked := invariants[rule.Invariant]; checked {
403				if holds {
404					status = StatusPass
405				} else {
406					status = StatusDefect
407				}
408			}
409			report.Rules = append(report.Rules, ReportRule{
410				ID:          rule.ID,
411				Kind:        rule.Kind,
412				Severity:    rule.Severity,
413				Invariant:   rule.Invariant,
414				RequiresABI: rule.RequiresABI,
415				Version:     rule.Version,
416				Status:      status,
417				Note:        note,
418			})
419			if status == StatusDefect {
420				evidence := note
421				if evidence == "" {
422					evidence = "invariant " + rule.Invariant + " does not hold"
423				}
424				report.Findings = append(report.Findings, ReportFinding{
425					ArtifactHash: hash,
426					RuleID:       rule.ID,
427					Version:      rule.Version,
428					Severity:     rule.Severity,
429					Invariant:    rule.Invariant,
430					Evidence:     evidence,
431				})
432			}
433		}
434		report.ReportID = ReportID(report)
435		return report, nil
436	}
437	
438	// canonicalRule is the order-independent view of a rule used for the id. The
439	// note is omitted when empty so reports built only from invariant booleans
440	// keep their original ids.
441	type canonicalRule struct {
442		ID          string `json:"id"`
443		Kind        string `json:"kind"`
444		Severity    string `json:"severity"`
445		Invariant   string `json:"invariant"`
446		RequiresABI bool   `json:"requiresABI"`
447		Version     string `json:"version"`
448		Status      string `json:"status"`
449		Note        string `json:"note,omitempty"`
450	}
451	
452	// canonicalFinding is the order-independent view of a finding used for the id.
453	type canonicalFinding struct {
454		ArtifactHash string `json:"artifactHash"`
455		RuleID       string `json:"ruleId"`
456		Version      string `json:"version"`
457		Severity     string `json:"severity"`
458		Invariant    string `json:"invariant"`
459		Evidence     string `json:"evidence"`
460	}
461	
462	// canonicalReport is the deterministic content a report id is computed from.
463	type canonicalReport struct {
464		ArtifactHash string             `json:"artifactHash"`
465		Name         string             `json:"name"`
466		Rules        []canonicalRule    `json:"rules"`
467		Findings     []canonicalFinding `json:"findings"`
468	}
469	
470	// canonicalize renders a report into its order-independent form.
471	func canonicalize(report Report) canonicalReport {
472		cr := canonicalReport{
473			ArtifactHash: report.Artifact.Hash,
474			Name:         report.Artifact.Name,
475		}
476		for _, rule := range report.Rules {
477			cr.Rules = append(cr.Rules, canonicalRule{
478				ID: rule.ID, Kind: rule.Kind, Severity: rule.Severity,
479				Invariant: rule.Invariant, RequiresABI: rule.RequiresABI,
480				Version: rule.Version, Status: rule.Status, Note: rule.Note,
481			})
482		}
483		sort.Slice(cr.Rules, func(i, j int) bool { return cr.Rules[i].ID < cr.Rules[j].ID })
484		for _, finding := range report.Findings {
485			cr.Findings = append(cr.Findings, canonicalFinding{
486				ArtifactHash: finding.ArtifactHash, RuleID: finding.RuleID,
487				Version: finding.Version, Severity: finding.Severity,
488				Invariant: finding.Invariant, Evidence: finding.Evidence,
489			})
490		}
491		sort.Slice(cr.Findings, func(i, j int) bool { return cr.Findings[i].RuleID < cr.Findings[j].RuleID })
492		return cr
493	}
494	
495	// ReportID returns the content-addressed identifier of a report. The id binds
496	// the artifact hash, name, complete rule definitions, the invariant value
497	// used by each rule (unchecked and explicit pass are distinct), and the
498	// findings. Rule order, invariant key order and unrelated invariant keys do
499	// not influence it.
500	func ReportID(r Report) string {
501		data, err := json.Marshal(canonicalize(r))
502		if err != nil {
503			panic(err) // canonical values are all strings and bools
504		}
505		sum := sha256.Sum256(data)
506		return hex.EncodeToString(sum[:])
507	}
508	
509	// validateReport checks every archive legality condition against r. It is the
510	// single definition of a legal report: the id and artifact hash are 64
511	// lowercase hex characters, the id matches the content, the artifact name is
512	// present, rule ids are present and unique with non-empty versions, statuses
513	// use the five recorded values, tool-missing and timeout notes are
514	// non-blank, and 发现缺陷 rules correspond one-to-one with findings whose
515	// artifact hash, version, severity, invariant and evidence match the rule.
516	// The same conditions apply to submissions and to stored archives: a
517	// recomputed id never makes an invalid report legal. fail is errInvalid for
518	// submissions and errCorrupt for stored archives.
519	func validateReport(r Report, fail func(string) error) error {
520		if !validReportID(r.ReportID) {
521			return fail("report id " + r.ReportID + " is not a 64-character lowercase hex string")
522		}
523		if r.Artifact.Name == "" {
524			return fail("report " + r.ReportID + " artifact name is required")
525		}
526		if !validReportID(r.Artifact.Hash) {
527			return fail("report " + r.ReportID + " artifact hash is not a 64-character lowercase hex string")
528		}
529		if ReportID(r) != r.ReportID {
530			return fail("report content does not match id " + r.ReportID)
531		}
532		seenRule := make(map[string]bool, len(r.Rules))
533		defectByID := make(map[string]ReportRule)
534		for _, rule := range r.Rules {
535			if rule.ID == "" {
536				return fail("report " + r.ReportID + " has a rule with an empty id")
537			}
538			if seenRule[rule.ID] {
539				return fail("report " + r.ReportID + " has duplicate rule id " + rule.ID)
540			}
541			seenRule[rule.ID] = true
542			if rule.Version == "" {
543				return fail("report " + r.ReportID + " rule " + rule.ID + " has an empty version")
544			}
545			switch rule.Status {
546			case StatusUnchecked, StatusPass, StatusDefect, StatusToolMissing, StatusTimeout:
547			default:
548				return fail("report " + r.ReportID + " rule " + rule.ID + " has unknown status " + rule.Status)
549			}
550			if (rule.Status == StatusToolMissing || rule.Status == StatusTimeout) && strings.TrimSpace(rule.Note) == "" {
551				return fail("report " + r.ReportID + " rule " + rule.ID + " status " + rule.Status + " has no note")
552			}
553			if rule.Status == StatusDefect {
554				defectByID[rule.ID] = rule
555			}
556		}
557		seenFinding := make(map[string]bool, len(r.Findings))
558		for _, f := range r.Findings {
559			if f.RuleID == "" {
560				return fail("report " + r.ReportID + " has a finding with an empty rule id")
561			}
562			rule, ok := defectByID[f.RuleID]
563			if !ok {
564				return fail("report " + r.ReportID + " finding for rule " + f.RuleID + " does not match a 发现缺陷 rule")
565			}
566			if seenFinding[f.RuleID] {
567				return fail("report " + r.ReportID + " has a duplicate finding for rule " + f.RuleID)
568			}
569			seenFinding[f.RuleID] = true
570			if f.ArtifactHash != r.Artifact.Hash {
571				return fail("report " + r.ReportID + " finding for rule " + f.RuleID + " has artifact hash " + f.ArtifactHash + ", want " + r.Artifact.Hash)
572			}
573			if f.Version != rule.Version {
574				return fail("report " + r.ReportID + " finding for rule " + f.RuleID + " has version " + f.Version + ", want " + rule.Version)
575			}
576			if f.Severity != rule.Severity {
577				return fail("report " + r.ReportID + " finding for rule " + f.RuleID + " has severity " + f.Severity + ", want " + rule.Severity)
578			}
579			if f.Invariant != rule.Invariant {
580				return fail("report " + r.ReportID + " finding for rule " + f.RuleID + " has invariant " + f.Invariant + ", want " + rule.Invariant)
581			}
582			wantEvidence := rule.Note
583			if wantEvidence == "" {
584				wantEvidence = "invariant " + rule.Invariant + " does not hold"
585			}
586			if f.Evidence != wantEvidence {
587				return fail("report " + r.ReportID + " finding for rule " + f.RuleID + " has evidence " + f.Evidence + ", want " + wantEvidence)
588			}
589		}
590		for id := range defectByID {
591			if !seenFinding[id] {
592				return fail("report " + r.ReportID + " defect rule " + id + " has no finding")
593			}
594		}
595		return nil
596	}
597	
598	// validStoredReport validates archive contents.
599	func validStoredReport(r Report) error {
600		return validateReport(r, func(msg string) error { return errCorrupt(msg) })
601	}
602	
603	// validSubmittedReport validates a submission before any store operation.
604	func validSubmittedReport(r Report) error {
605		return validateReport(r, func(msg string) error { return errInvalid(msg) })
606	}
607	
608	// firstInvalidUTF8ByteInString returns the first byte that is not valid UTF-8
609	// inside s. A Go string can carry any bytes, including bytes no JSON text may
610	// contain: json.Marshal (and therefore the canonical marshalling inside
611	// ReportID) silently replaces such a byte with U+FFFD instead of failing, so
612	// neither the id/content check nor the archive round trip can see it.
613	func firstInvalidUTF8ByteInString(s string) (byte, bool) {
614		for i := 0; i < len(s); {
615			r, size := utf8.DecodeRuneInString(s[i:])
616			if r == utf8.RuneError && size == 1 {
617				return s[i], true
618			}
619			i += size
620		}
621		return 0, false
622	}
623	
624	// validateSubmittedText is the in-memory counterpart of the JSON character
625	// gates in ParseAuditInput and loadStoredReport. SaveReport accepts a Report
626	// built directly by a Go caller, whose strings never passed through JSON
627	// decoding; encoding/json marshals such a value without an error while
628	// replacing every invalid UTF-8 byte with U+FFFD, and ReportID computes from
629	// the same rewritten canonical form, so the recomputed id and the
630	// rule/finding correspondence would all match an archive whose text no
631	// longer equals what the caller handed over. Every caller-supplied string is
632	// therefore checked on the raw object — reportId, artifact name and hash,
633	// each rule definition field and status note, and each finding binding field
634	// and evidence — independently of which rules produced defects and of
635	// whether the report carries any finding at all. The rejection is an input
636	// error naming the exact field, with the array position of rules and
637	// findings, and it runs before any filesystem operation.
638	func validateSubmittedText(r Report) error {
639		check := func(field, value string) error {
640			if b, bad := firstInvalidUTF8ByteInString(value); bad {
641				return errInvalid(fmt.Sprintf("invalid UTF-8 byte 0x%02x in report field %s", b, field))
642			}
643			return nil
644		}
645		if err := check("reportId", r.ReportID); err != nil {
646			return err
647		}
648		if err := check("artifact.name", r.Artifact.Name); err != nil {
649			return err
650		}
651		if err := check("artifact.hash", r.Artifact.Hash); err != nil {
652			return err
653		}
654		ruleFields := []string{"id", "kind", "severity", "invariant", "version", "status", "note"}
655		for i, rule := range r.Rules {
656			values := []string{rule.ID, rule.Kind, rule.Severity, rule.Invariant, rule.Version, rule.Status, rule.Note}
657			for j, value := range values {
658				if err := check(fmt.Sprintf("rules[%d].%s", i, ruleFields[j]), value); err != nil {
659					return err
660				}
661			}
662		}
663		findingFields := []string{"artifactHash", "ruleId", "version", "severity", "invariant", "evidence"}
664		for i, finding := range r.Findings {
665			values := []string{finding.ArtifactHash, finding.RuleID, finding.Version, finding.Severity, finding.Invariant, finding.Evidence}
666			for j, value := range values {
667				if err := check(fmt.Sprintf("findings[%d].%s", i, findingFields[j]), value); err != nil {
668					return err
669				}
670			}
671		}
672		return nil
673	}
674	
675	// duplicateArchiveError classifies an archive that repeats a JSON member as
676	// corrupt and names the requested report id, the decoded member name and the
677	// object carrying it (with array position and rule id when applicable).
678	func duplicateArchiveError(id string, data []byte, dup *duplicateMemberError) error {
679		return errCorrupt("report " + id + " archive is corrupt: " + duplicateMemberMessage(data, dup))
680	}
681	
682	// characterArchiveError classifies an archive whose bytes are not legal JSON
683	// text — an invalid UTF-8 byte anywhere, or an unpaired / wrongly ordered
684	// surrogate escape inside any member name or string value, including unknown
685	// extension members — as corrupt and names the requested report id together
686	// with the precise byte offset, line/column and JSON path. It is the
687	// read-side counterpart of the submission gate in ParseAuditInput: the decode
688	// below would otherwise replace both problems with U+FFFD and could accept a
689	// rewritten archive whose id and rule/finding evidence happened to match.
690	func characterArchiveError(id string, charErr *charEncodingError) error {
691		return errCorrupt("report " + id + " archive is corrupt: " + charErr.Error())
692	}
693	
694	// reportShape is the fixed-field shape of a stored report archive: the agreed
695	// spellings at the top level and inside the artifact, every rule and every
696	// finding. The trusted content of a report is carried by these fixed fields
697	// alone; case variants, whitespace-padded names and unknown members are
698	// extension data and never reach the decoder.
699	var reportShape = fixedShape{
700		keys: []string{"reportId", "artifact", "rules", "findings"},
701		objects: map[string]fixedShape{
702			"artifact": {keys: []string{"name", "hash"}},
703		},
704		arrays: map[string]fixedShape{
705			"rules":    {keys: []string{"id", "kind", "severity", "invariant", "requiresABI", "version", "status", "note"}},
706			"findings": {keys: []string{"artifactHash", "ruleId", "version", "severity", "invariant", "evidence"}},
707		},
708	}
709	
710	// strictReportJSON rewrites archive bytes to the fixed report fields under
711	// their original spelling; see fixedShape for the recognition convention
712	// shared with the submission side.
713	func strictReportJSON(data []byte) ([]byte, error) {
714		return strictFixedJSON(data, reportShape)
715	}
716	
717	// validateArchiveRequiresABI is the read-side counterpart of the submission
718	// check in validateFormalRequiresABI. A ReportRule.RequiresABI is a Go bool,
719	// so decoding the strict archive straight into Report turns a formal null
720	// member into the zero value false: an archive that wrote "requiresABI":null
721	// would read byte-for-byte like one that wrote false, the recomputed id and
722	// the rule/finding correspondence would all pass on that laundered value, and
723	// a diff could even compare it as an unchanged rule. When the formal member
724	// is present its value must therefore be the JSON boolean true or false;
725	// null, a string, a number, an object or an array makes the whole archive
726	// corrupt, independently of the rule's check status and of whether it has a
727	// finding — the offending rule is never skipped and no partial report is
728	// returned. An omitted member still means false. The strict rewrite dropped
729	// extension members, so a case-variant or whitespace-padded name is invisible
730	// here: a boolean it carries neither supplies nor rescues the formal value,
731	// and a null it carries never reaches this check.
732	func validateArchiveRequiresABI(strict []byte, id string) error {
733		var top struct {
734			Rules []map[string]json.RawMessage `json:"rules"`
735		}
736		if err := json.Unmarshal(strict, &top); err != nil {
737			return errCorrupt("invalid JSON in report " + id + ": " + err.Error())
738		}
739		for _, rule := range top.Rules {
740			where := "rule"
741			if raw, ok := rule["id"]; ok {
742				var ruleID string
743				if err := json.Unmarshal(raw, &ruleID); err == nil && ruleID != "" {
744					where = "rule " + ruleID
745				}
746			}
747			raw, ok := rule["requiresABI"]
748			if !ok {
749				continue
750			}
751			var token any
752			if err := json.Unmarshal(raw, &token); err != nil {
753				return errCorrupt("report " + id + " archive is corrupt: " + where + ": requiresABI must be a boolean")
754			}
755			if _, isBool := token.(bool); !isBool {
756				return errCorrupt("report " + id + " archive is corrupt: " + where + ": requiresABI must be a boolean")
757			}
758		}
759		return nil
760	}
761	
762	// loadStoredReport parses archive bytes for id and fully validates them.
763	func loadStoredReport(data []byte, id string) (Report, error) {
764		// Read-side counterpart of the submission character gate in
765		// ParseAuditInput. As with a repeated member, json.Unmarshal silently
766		// rewrites an invalid UTF-8 byte and an unpaired or wrongly ordered
767		// surrogate escape into U+FFFD, so an archive whose note and evidence both
768		// carried the substitution character could have those two spots changed to
769		// lone surrogate escapes and still decode to byte-identical content: the
770		// recomputed id and the rule/finding evidence comparison would then pass on
771		// the rewritten copy. Every raw string literal is checked first — member
772		// names and values, at every depth, inside unknown extension members too —
773		// and the whole archive is corrupt when any character is illegal, whatever
774		// id the rewritten content would compute.
775		if charErr := validateJSONCharacters(data); charErr != nil {
776			return Report{}, characterArchiveError(id, charErr)
777		}
778		// Read-side counterpart of the submission check: json.Unmarshal silently
779		// keeps the last value for a repeated member, so an archive that writes a
780		// rule status as 发现缺陷 and then 通过 would decode to whichever came
781		// last. The recomputed id and the rule/finding correspondence all operate
782		// on that last-wins value and could therefore pass, accepting an archive
783		// with two conflicting conclusions. Any repeated member in any object
784		// makes the archive corrupt, regardless of the last value.
785		if dup := findDuplicateJSONMember(data); dup != nil {
786			return Report{}, duplicateArchiveError(id, data, dup)
787		}
788		strict, err := strictReportJSON(data)
789		if err != nil {
790			return Report{}, errCorrupt("invalid JSON in report " + id + ": " + err.Error())
791		}
792		// Check the formal requiresABI member against its raw JSON token before
793		// decoding into the Go bool below; otherwise a null value would silently
794		// become the zero value false and could pass every later check, including
795		// the content id, as if the archive had explicitly said false.
796		if err := validateArchiveRequiresABI(strict, id); err != nil {
797			return Report{}, err
798		}
799		var r Report
800		if err := json.Unmarshal(strict, &r); err != nil {
801			return Report{}, errCorrupt("invalid JSON in report " + id + ": " + err.Error())
802		}
803		if r.ReportID != id {
804			return Report{}, errCorrupt("report id " + r.ReportID + " does not match requested id " + id)
805		}
806		if err := validStoredReport(r); err != nil {
807			return Report{}, err
808		}
809		return r, nil
810	}
811	
812	// saveReportHook, when set, is invoked after the archive existence check and
813	// before the atomic publish. It lets tests simulate another process racing to
814	// claim the same report id.
815	var saveReportHook func(finalPath string)
816	
817	// SaveReport persists a report under the store directory. The store is safe
818	// for concurrent writers: identical reports share one file and all
819	// submissions succeed, different reports never overwrite each other, and
820	// readers only ever observe complete files. A submission is fully validated
821	// before any store operation, so an invalid report creates no store and no
822	// files. Every string in a directly constructed report must be valid UTF-8:
823	// json.Marshal would otherwise rewrite an invalid byte to U+FFFD while the
824	// content-addressed id matched the rewritten copy, reporting success for an
825	// archive whose text differs from the caller's; such a report is rejected as
826	// an input error before the store directory is touched. A pre-existing file
827	// with the same id must be a valid archive of the same report; a corrupted
828	// archive makes the submission fail while keeping the original file, even
829	// when the corruption appears only during the save. The first successfully
830	// archived bytes are never replaced by later submissions.
831	func SaveReport(dir string, r Report) error {
832		if err := validateSubmittedText(r); err != nil {
833			return err
834		}
835		if err := validSubmittedReport(r); err != nil {
836			return err
837		}
838		if err := os.MkdirAll(dir, 0o755); err != nil {
839			return err
840		}
841		finalPath := filepath.Join(dir, r.ReportID+".json")
842		if existing, err := os.ReadFile(finalPath); err == nil {
843			if _, err := loadStoredReport(existing, r.ReportID); err != nil {
844				return err
845			}
846			return nil
847		} else if !os.IsNotExist(err) {
848			return err
849		}
850		data, err := json.Marshal(r)
851		if err != nil {
852			return err
853		}
854		tmp, err := os.CreateTemp(dir, ".report-*.tmp")
855		if err != nil {
856			return err
857		}
858		tmpPath := tmp.Name()
859		cleanup := func() { os.Remove(tmpPath) }
860		if _, err := tmp.Write(data); err != nil {
861			tmp.Close()
862			cleanup()
863			return err
864		}
865		if err := tmp.Sync(); err != nil {
866			tmp.Close()
867			cleanup()
868			return err
869		}
870		if err := tmp.Close(); err != nil {
871			cleanup()
872			return err
873		}
874		if saveReportHook != nil {
875			saveReportHook(finalPath)
876		}
877		if err := os.Link(tmpPath, finalPath); err != nil {
878			cleanup()
879			if os.IsExist(err) {
880				existing, readErr := os.ReadFile(finalPath)
881				if readErr != nil {
882					return readErr
883				}
884				if _, err := loadStoredReport(existing, r.ReportID); err != nil {
885					return err
886				}
887				return nil
888			}
889			return err
890		}
891		cleanup()
892		return nil
893	}
894	
895	// LoadReport reads and verifies a report by id. The id must be 64 lowercase
896	// hex characters; missing, corrupted or tampered archives produce a clear
897	// error. The store is only read, never created or modified.
898	func LoadReport(dir, id string) (Report, error) {
899		if !validReportID(id) {
900			return Report{}, errInvalid("invalid report id " + id + ": want 64 lowercase hex characters")
901		}
902		data, err := os.ReadFile(filepath.Join(dir, id+".json"))
903		if err != nil {
904			if os.IsNotExist(err) {
905				return Report{}, errNotFound("report " + id + " not found")
906			}
907			return Report{}, err
908		}
909		return loadStoredReport(data, id)
910	}
911	
912	type errNotFound string
913	
914	func (e errNotFound) Error() string { return string(e) }
915	
916	type errCorrupt string
917	
918	func (e errCorrupt) Error() string { return string(e) }
919

