1	package contractsentinel
2	
3	import (
4		"errors"
5		"strings"
6		"testing"
7	)
8	
9	// 直接返回缺陷列表的既有调用方式（Run）业务回归保障。报告路径
10	// （BuildReport 及其归档）由 report_test.go 等覆盖；本文件保护两种调用
11	// 方式在不变式布尔值审计上的一致业务语义，同时保留各自的公开行为差异：
12	// Run 直接返回 Finding 列表，规则版本可缺省，输入不足即整体失败。
13	
14	// findingKey 是一条缺陷的业务归属。
15	type findingKey struct {
16		Rule      string
17		Severity  string
18		Invariant string
19		Evidence  string
20	}
21	
22	func findingSet(findings []Finding) map[findingKey]int {
23		set := make(map[findingKey]int, len(findings))
24		for _, f := range findings {
25			set[findingKey{f.Rule, f.Severity, f.Invariant, f.Evidence}]++
26		}
27		return set
28	}
29	
30	// 一份合约产物可同时适用多条规则：每个不变式为 false 的规则各自产生缺陷，
31	// 缺陷保留所属规则、严重级别和不变式名。
32	func TestRunFalseInvariantProducesDefectPerReferencingRule(t *testing.T) {
33		rules := []Rule{
34			{ID: "r1", Kind: "static", Severity: "high", Invariant: "inv-a"},
35			{ID: "r2", Kind: "static", Severity: "medium", Invariant: "inv-b"},
36			{ID: "r3", Kind: "static", Severity: "low", Invariant: "inv-c"},
37		}
38		invariants := map[string]bool{"inv-a": false, "inv-b": false, "inv-c": false}
39		findings, err := Run(sampleArtifact(), rules, invariants)
40		if err != nil {
41			t.Fatal(err)
42		}
43		if len(findings) != 3 {
44			t.Fatalf("findings = %d, want one defect per rule (3): %+v", len(findings), findings)
45		}
46		byRule := map[string]Finding{}
47		for _, f := range findings {
48			byRule[f.Rule] = f
49		}
50		for _, want := range []struct {
51			rule, severity, invariant string
52		}{
53			{"r1", "high", "inv-a"},
54			{"r2", "medium", "inv-b"},
55			{"r3", "low", "inv-c"},
56		} {
57			f, ok := byRule[want.rule]
58			if !ok {
59				t.Errorf("missing finding for rule %s: %+v", want.rule, findings)
60				continue
61			}
62			if f.Severity != want.severity {
63				t.Errorf("rule %s severity = %q, want %q", want.rule, f.Severity, want.severity)
64			}
65			if f.Invariant != want.invariant {
66				t.Errorf("rule %s invariant = %q, want %q", want.rule, f.Invariant, want.invariant)
67			}
68			if f.Evidence != "invariant "+want.invariant+" does not hold" {
69				t.Errorf("rule %s evidence = %q, want %q", want.rule, f.Evidence,
70					"invariant "+want.invariant+" does not hold")
71			}
72		}
73	}
74	
75	// 值为 true 或根本没有提供该名字，都不能产生缺陷；两者都没有 finding，
76	// 但它们是不同输入（报告路径必须仍能区分“通过”和“未检查”，见
77	// TestRunParityWithReportStatuses）。
78	func TestRunTrueOrAbsentInvariantProducesNoFinding(t *testing.T) {
79		rules := []Rule{
80			{ID: "pass", Kind: "static", Severity: "high", Invariant: "holds"},
81			{ID: "unchecked", Kind: "static", Severity: "high", Invariant: "never-supplied"},
82		}
83		for name, invariants := range map[string]map[string]bool{
84			"true only":   {"holds": true},
85			"false other": {"holds": true, "other": false},
86			"empty":       {},
87			"nil":         nil,
88		} {
89			findings, err := Run(sampleArtifact(), rules, invariants)
90			if err != nil {
91				t.Fatalf("%s: %v", name, err)
92			}
93			if len(findings) != 0 {
94				t.Errorf("%s: true/absent invariants must produce no findings, got %+v", name, findings)
95			}
96		}
97	}
98	
99	// 输入中没有任何规则引用的 false 值不能凭空形成发现。
100	func TestRunUnreferencedFalseInvariantProducesNoFinding(t *testing.T) {
101		rules := []Rule{
102			{ID: "r1", Kind: "static", Severity: "high", Invariant: "referenced"},
103		}
104		invariants := map[string]bool{"referenced": true, "nobody-uses-me": false, "also-orphan": false}
105		findings, err := Run(sampleArtifact(), rules, invariants)
106		if err != nil {
107			t.Fatal(err)
108		}
109		if len(findings) != 0 {
110			t.Fatalf("false invariants referenced by no rule must create no finding: %+v", findings)
111		}
112	}
113	
114	// 证据固定为 invariant <不变式名> does not hold，名字采用规则中的原值：
115	// 大小写、空白和点号按原样保留，不做归一化或修剪。
116	func TestRunEvidenceUsesInvariantNameAsWritten(t *testing.T) {
117		written := "Balance.Monotonic v2 "
118		rules := []Rule{
119			{ID: "r1", Kind: "static", Severity: "critical", Invariant: written},
120		}
121		findings, err := Run(sampleArtifact(), rules, map[string]bool{written: false})
122		if err != nil {
123			t.Fatal(err)
124		}
125		if len(findings) != 1 {
126			t.Fatalf("findings = %d, want 1", len(findings))
127		}
128		want := "invariant " + written + " does not hold"
129		if findings[0].Evidence != want {
130			t.Errorf("evidence = %q, want %q (name must be the rule's original value)",
131				findings[0].Evidence, want)
132		}
133		if findings[0].Invariant != written {
134			t.Errorf("invariant = %q, want the original spelling %q", findings[0].Invariant, written)
135		}
136	}
137	
138	// 两条不同规则引用同一个不变式：值为 false 时必须分别留下各自的缺陷，
139	// 不能按不变式名合并成一条，也不能把第一条规则的严重级别带到另一条上。
140	func TestRunSharedFalseInvariantGivesTwoFindingsWithOwnSeverity(t *testing.T) {
141		rules := []Rule{
142			{ID: "rule-a", Kind: "static", Severity: "high", Invariant: "shared"},
143			{ID: "rule-b", Kind: "symbolic", Severity: "low", Invariant: "shared"},
144		}
145		findings, err := Run(sampleArtifact(), rules, map[string]bool{"shared": false})
146		if err != nil {
147			t.Fatal(err)
148		}
149		if len(findings) != 2 {
150			t.Fatalf("findings = %d, want 2 (one per rule, not merged by invariant name)", len(findings))
151		}
152		byRule := map[string]Finding{}
153		for _, f := range findings {
154			if _, dup := byRule[f.Rule]; dup {
155				t.Fatalf("rule %s produced duplicated findings: %+v", f.Rule, findings)
156			}
157			byRule[f.Rule] = f
158		}
159		a, okA := byRule["rule-a"]
160		b, okB := byRule["rule-b"]
161		if !okA || !okB {
162			t.Fatalf("expected findings for both rules, got %+v", findings)
163		}
164		if a.Severity != "high" {
165			t.Errorf("rule-a severity = %q, want high", a.Severity)
166		}
167		if b.Severity != "low" {
168			t.Errorf("rule-b severity = %q, want its own severity low, not %q", b.Severity, a.Severity)
169		}
170		for _, f := range []Finding{a, b} {
171			if f.Invariant != "shared" {
172				t.Errorf("rule %s invariant = %q, want shared", f.Rule, f.Invariant)
173			}
174			if f.Evidence != "invariant shared does not hold" {
175				t.Errorf("rule %s evidence = %q", f.Rule, f.Evidence)
176			}
177		}
178	}
179	
180	// 同一不变式值为 true 时，两条规则都不产生缺陷。
181	func TestRunSharedTrueInvariantGivesNoFinding(t *testing.T) {
182		rules := []Rule{
183			{ID: "rule-a", Kind: "static", Severity: "high", Invariant: "shared"},
184			{ID: "rule-b", Kind: "symbolic", Severity: "low", Invariant: "shared"},
185		}
186		findings, err := Run(sampleArtifact(), rules, map[string]bool{"shared": true})
187		if err != nil {
188			t.Fatal(err)
189		}
190		if len(findings) != 0 {
191			t.Fatalf("a shared true invariant must give no findings, got %+v", findings)
192		}
193	}
194	
195	// 直接返回列表的既有调用方式允许规则没有版本：缺省 Version 仍应正常给出
196	// 原有结论，不能套用报告提交的版本必填要求。
197	func TestRunAllowsRulesWithoutVersion(t *testing.T) {
198		rules := []Rule{
199			{ID: "no-version", Kind: "static", Severity: "high", Invariant: "inv"},
200		}
201		findings, err := Run(sampleArtifact(), rules, map[string]bool{"inv": false})
202		if err != nil {
203			t.Fatalf("Run must not require a rule version: %v", err)
204		}
205		if len(findings) != 1 || findings[0].Rule != "no-version" {
206			t.Fatalf("expected the original defect conclusion, got %+v", findings)
207		}
208		// 对照：同一份规则定义走报告路径必须因版本缺失而失败，两条调用方式
209		// 各自的公开行为都保留。
210		if _, err := BuildReport(sampleArtifact(), rules, map[string]bool{"inv": false}, nil); err == nil {
211			t.Fatal("BuildReport must keep requiring a version; only the list API omits it")
212		}
213	}
214	
215	// 缺少执行规则所需的产物内容是输入错误（errInvalid），错误必须指出缺少的
216	// 内容及对应规则；结论与是否提供该规则的不变式值无关。
217	func TestRunRequiresABIMissing(t *testing.T) {
218		rules := []Rule{{ID: "abi-rule", Kind: "static", Severity: "high",
219			Invariant: "inv", RequiresABI: true}}
220		artifact := Artifact{Name: "Vault", ABI: "", Bytecode: "0x6080", Source: "Vault.sol"}
221		for name, invariants := range map[string]map[string]bool{
222			"false invariant":  {"inv": false},
223			"true invariant":   {"inv": true},
224			"absent invariant": {"other": true},
225			"no invariants":    nil,
226		} {
227			findings, err := Run(artifact, rules, invariants)
228			if err == nil {
229				t.Errorf("%s: expected failure for the empty ABI", name)
230				continue
231			}
232			var ei errInvalid
233			if !errors.As(err, &ei) {
234				t.Errorf("%s: expected an input error (errInvalid), got %T: %v", name, err, err)
235			}
236			if !strings.Contains(err.Error(), "abi") {
237				t.Errorf("%s: error must point at the missing ABI: %v", name, err)
238			}
239			if !strings.Contains(err.Error(), "abi-rule") {
240				t.Errorf("%s: error must name the rule: %v", name, err)
241			}
242			if findings != nil {
243				t.Errorf("%s: failure must return no findings at all, got %+v", name, findings)
244			}
245		}
246	}
247	
248	// symbolic 规则遇到空字节码同样整体失败，与不变式值无关。
249	func TestRunSymbolicMissingBytecode(t *testing.T) {
250		rules := []Rule{{ID: "sym-rule", Kind: "symbolic", Severity: "critical", Invariant: "inv"}}
251		artifact := Artifact{Name: "Vault", ABI: "abi", Bytecode: "", Source: "Vault.sol"}
252		for name, invariants := range map[string]map[string]bool{
253			"false invariant":  {"inv": false},
254			"true invariant":   {"inv": true},
255			"absent invariant": nil,
256		} {
257			findings, err := Run(artifact, rules, invariants)
258			if err == nil {
259				t.Errorf("%s: expected failure for the empty bytecode", name)
260				continue
261			}
262			var ei errInvalid
263			if !errors.As(err, &ei) {
264				t.Errorf("%s: expected an input error (errInvalid), got %T: %v", name, err, err)
265			}
266			if !strings.Contains(err.Error(), "bytecode") {
267				t.Errorf("%s: error must point at the missing bytecode: %v", name, err)
268			}
269			if !strings.Contains(err.Error(), "sym-rule") {
270				t.Errorf("%s: error must name the rule: %v", name, err)
271			}
272			if findings != nil {
273				t.Errorf("%s: failure must return no findings at all, got %+v", name, findings)
274			}
275		}
276	}
277	
278	// 即使同次输入中排在前面的规则已能确认缺陷，输入不足也必须整次审计失败：
279	// 不能返回那部分发现。
280	func TestRunMissingContentFailsWholeAuditWithoutPartialFindings(t *testing.T) {
281		rules := []Rule{
282			{ID: "already-defect", Kind: "static", Severity: "high", Invariant: "broken"},
283			{ID: "needs-abi", Kind: "static", Severity: "medium", Invariant: "other", RequiresABI: true},
284		}
285		artifact := Artifact{Name: "Vault", ABI: "", Bytecode: "0x6080", Source: "Vault.sol"}
286		findings, err := Run(artifact, rules, map[string]bool{"broken": false, "other": false})
287		if err == nil {
288			t.Fatal("the audit must fail when a rule lacks its ABI")
289		}
290		if !strings.Contains(err.Error(), "needs-abi") {
291			t.Fatalf("error must name the rule missing content: %v", err)
292		}
293		if findings != nil {
294			t.Fatalf("no partial findings may be returned on failure, got %+v", findings)
295		}
296	}
297	
298	// 同样，symbolic 规则的空字节码不能被前面规则已确认的缺陷掩盖。
299	func TestRunMissingBytecodeFailsWholeAuditWithoutPartialFindings(t *testing.T) {
300		rules := []Rule{
301			{ID: "already-defect", Kind: "static", Severity: "high", Invariant: "broken"},
302			{ID: "needs-bytecode", Kind: "symbolic", Severity: "critical", Invariant: "other"},
303		}
304		artifact := Artifact{Name: "Vault", ABI: "abi", Bytecode: "", Source: "Vault.sol"}
305		findings, err := Run(artifact, rules, map[string]bool{"broken": false, "other": false})
306		if err == nil {
307			t.Fatal("the audit must fail when a symbolic rule lacks bytecode")
308		}
309		if !strings.Contains(err.Error(), "needs-bytecode") {
310			t.Fatalf("error must name the rule missing content: %v", err)
311		}
312		if findings != nil {
313			t.Fatalf("no partial findings may be returned on failure, got %+v", findings)
314		}
315	}
316	
317	// 为规则补齐所需内容后，相同布尔值应恢复正常结论；先前的输入不足绝不能被
318	// 记作合约缺陷。
319	func TestRunRecoversAfterSupplyingRequiredContent(t *testing.T) {
320		rules := []Rule{
321			{ID: "abi-rule", Kind: "static", Severity: "high", Invariant: "inv-a", RequiresABI: true},
322			{ID: "sym-rule", Kind: "symbolic", Severity: "critical", Invariant: "inv-b"},
323		}
324		invariants := map[string]bool{"inv-a": false, "inv-b": false}
325	
326		incomplete := Artifact{Name: "Vault", ABI: "", Bytecode: "", Source: "Vault.sol"}
327		if findings, err := Run(incomplete, rules, invariants); err == nil {
328			t.Fatalf("empty ABI and bytecode must fail, got findings %+v", findings)
329		}
330	
331		complete := Artifact{Name: "Vault", ABI: `[{"name":"withdraw"}]`, Bytecode: "0x6080", Source: "Vault.sol"}
332		findings, err := Run(complete, rules, invariants)
333		if err != nil {
334			t.Fatalf("with the required content supplied the same booleans must audit: %v", err)
335		}
336		if len(findings) != 2 {
337			t.Fatalf("findings = %d, want 2 real defects after content is supplied", len(findings))
338		}
339		set := findingSet(findings)
340		for _, want := range []findingKey{
341			{"abi-rule", "high", "inv-a", "invariant inv-a does not hold"},
342			{"sym-rule", "critical", "inv-b", "invariant inv-b does not hold"},
343		} {
344			if set[want] != 1 {
345				t.Errorf("missing expected finding %+v; got %+v", want, findings)
346			}
347		}
348	}
349	
350	// 产物名为必填输入；空名字是输入错误且不返回任何发现。
351	func TestRunRequiresArtifactName(t *testing.T) {
352		rules := []Rule{{ID: "r1", Kind: "static", Severity: "high", Invariant: "inv"}}
353		findings, err := Run(Artifact{ABI: "abi", Bytecode: "0x1"}, rules, map[string]bool{"inv": false})
354		if err == nil {
355			t.Fatal("an empty artifact name must be an input error")
356		}
357		var ei errInvalid
358		if !errors.As(err, &ei) {
359			t.Fatalf("expected errInvalid, got %T: %v", err, err)
360		}
361		if findings != nil {
362			t.Fatalf("failure must return no findings, got %+v", findings)
363		}
364	}
365	
366	// 对于规则版本完整的同一份有效输入，两种调用方式的缺陷归属（规则、严重
367	// 级别、不变式名）与证据必须一致；报告中的每条 finding 还应绑定本次产物
368	// 哈希和对应规则版本。报告路径上，true 是“通过”、未提供是“未检查”，
369	// 两者不能因为都没有 finding 而混为一种结论。
370	func TestRunParityWithReportFindings(t *testing.T) {
371		rules := []Rule{
372			{ID: "reentrancy-guard", Kind: "static", Severity: "high", Invariant: "no-reentrant-withdraw", Version: "1.0.0"},
373			{ID: "access-control", Kind: "static", Severity: "medium", Invariant: "owner-only-withdraw", RequiresABI: true, Version: "2.1.0"},
374			{ID: "invariant-preserved", Kind: "symbolic", Severity: "critical", Invariant: "balance-monotonic", Version: "0.9.0"},
375			{ID: "shared-a", Kind: "static", Severity: "high", Invariant: "shared", Version: "3.0.0"},
376			{ID: "shared-b", Kind: "static", Severity: "low", Invariant: "shared", Version: "3.0.0"},
377			{ID: "passing", Kind: "static", Severity: "low", Invariant: "holds-explicitly", Version: "4.0.0"},
378			{ID: "never-checked", Kind: "static", Severity: "low", Invariant: "no-value-given", Version: "5.0.0"},
379		}
380		invariants := map[string]bool{
381			"no-reentrant-withdraw": false, // defect
382			"owner-only-withdraw":   true,  // pass
383			"balance-monotonic":     false, // defect
384			"shared":                false, // two defects, one per rule
385			"holds-explicitly":      true,  // pass
386			"orphan-false":          false, // referenced by nobody: no finding either way
387		}
388		artifact := sampleArtifact()
389	
390		listFindings, err := Run(artifact, rules, invariants)
391		if err != nil {
392			t.Fatal(err)
393		}
394		report, err := BuildReport(artifact, rules, invariants, nil)
395		if err != nil {
396			t.Fatal(err)
397		}
398	
399		// “通过”与“未检查”在报告中分别显示，不能合并。
400		statusByID := map[string]string{}
401		for _, r := range report.Rules {
402			statusByID[r.ID] = r.Status
403		}
404		if statusByID["passing"] != StatusPass {
405			t.Errorf("passing = %q, want %q", statusByID["passing"], StatusPass)
406		}
407		if statusByID["never-checked"] != StatusUnchecked {
408			t.Errorf("never-checked = %q, want %q", statusByID["never-checked"], StatusUnchecked)
409		}
410		if statusByID["access-control"] != StatusPass {
411			t.Errorf("access-control = %q, want %q", statusByID["access-control"], StatusPass)
412		}
413	
414		// 缺陷集合一致：归属与证据逐条相同（顺序可能不同，按集合比较）。
415		listSet := findingSet(listFindings)
416		reportSet := make(map[findingKey]int, len(report.Findings))
417		hash := ArtifactHash(artifact)
418		versionByID := make(map[string]string, len(rules))
419		for _, r := range rules {
420			versionByID[r.ID] = r.Version
421		}
422		for _, f := range report.Findings {
423			reportSet[findingKey{f.RuleID, f.Severity, f.Invariant, f.Evidence}]++
424			// 每条报告 finding 绑定本次产物哈希与对应规则版本。
425			if f.ArtifactHash != hash {
426				t.Errorf("finding %s artifact hash = %q, want %q", f.RuleID, f.ArtifactHash, hash)
427			}
428			if f.Version == "" {
429				t.Errorf("finding %s must bind the rule version", f.RuleID)
430			} else if f.Version != versionByID[f.RuleID] {
431				t.Errorf("finding %s version = %q, want %q", f.RuleID, f.Version, versionByID[f.RuleID])
432			}
433		}
434		if len(listSet) != len(reportSet) {
435			t.Fatalf("Run gives %d distinct findings, report gives %d:\nlist=%+v\nreport=%+v",
436				len(listSet), len(reportSet), listFindings, report.Findings)
437		}
438		for key, n := range listSet {
439			if reportSet[key] != n {
440				t.Errorf("finding %+v count = %d from Run but %d from report", key, n, reportSet[key])
441			}
442		}
443		for key, n := range reportSet {
444			if listSet[key] != n {
445				t.Errorf("finding %+v count = %d from report but %d from Run", key, n, listSet[key])
446			}
447		}
448	
449		// 具体期望：4 条缺陷，包括共享同一 false 不变式的两条规则。
450		wantKeys := map[findingKey]bool{
451			{"reentrancy-guard", "high", "no-reentrant-withdraw", "invariant no-reentrant-withdraw does not hold"}: true,
452			{"invariant-preserved", "critical", "balance-monotonic", "invariant balance-monotonic does not hold"}:  true,
453			{"shared-a", "high", "shared", "invariant shared does not hold"}:                                       true,
454			{"shared-b", "low", "shared", "invariant shared does not hold"}:                                        true,
455		}
456		if len(listFindings) != len(wantKeys) {
457			t.Fatalf("expected %d defects, got %d: %+v", len(wantKeys), len(listFindings), listFindings)
458		}
459		for key := range listSet {
460			if !wantKeys[key] {
461				t.Errorf("unexpected defect %+v", key)
462			}
463		}
464	}
465	
466	// 把不变式值翻转后，两种调用方式应同步地从“有缺陷”变为“无缺陷”。
467	func TestRunParityWithReportWhenInvariantHolds(t *testing.T) {
468		rules := []Rule{
469			{ID: "r1", Kind: "static", Severity: "high", Invariant: "inv", Version: "1"},
470			{ID: "r2", Kind: "symbolic", Severity: "low", Invariant: "inv", Version: "2"},
471		}
472		artifact := sampleArtifact()
473		listFindings, err := Run(artifact, rules, map[string]bool{"inv": true})
474		if err != nil {
475			t.Fatal(err)
476		}
477		report, err := BuildReport(artifact, rules, map[string]bool{"inv": true}, nil)
478		if err != nil {
479			t.Fatal(err)
480		}
481		if len(listFindings) != 0 || len(report.Findings) != 0 {
482			t.Fatalf("true invariant must give no findings on either path: %+v %+v",
483				listFindings, report.Findings)
484		}
485	}
486

